import type { LucideIcon } from 'lucide-react'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type AboutValue = {
  title: string
  description: string
  icon?: LucideIcon
}

export type AboutValuesSectionProps = {
  eyebrow?: string
  title: string
  description: string
  values: AboutValue[]
  statement?: string
  className?: string
}

export function AboutValuesSection({
  eyebrow = 'Sobre nós',
  title,
  description,
  values,
  statement,
  className,
}: AboutValuesSectionProps) {
  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="grid gap-10 lg:grid-cols-[0.9fr_1.1fr] lg:gap-16">
          <header className="lg:sticky lg:top-24 lg:self-start">
            <p className="text-sm font-semibold uppercase tracking-[0.18em] text-primary">
              {eyebrow}
            </p>
            <h2 className="mt-4 text-balance text-3xl font-bold tracking-tight md:text-5xl">
              {title}
            </h2>
            <p className="mt-5 max-w-xl text-lg leading-8 text-muted-foreground">{description}</p>
            {statement ? (
              <p className="mt-8 border-l-2 border-primary pl-5 text-lg font-medium leading-8">
                {statement}
              </p>
            ) : null}
          </header>

          <div className="grid gap-4 sm:grid-cols-2">
            {values.map((value, index) => {
              const Icon = value.icon
              return (
                <article
                  key={value.title}
                  className={cn(
                    'group min-h-56 rounded-3xl border bg-card p-6 transition duration-300 hover:border-primary/30 hover:shadow-lg',
                    index === 0 && 'sm:col-span-2 sm:min-h-64',
                  )}
                >
                  <div className="flex items-start justify-between">
                    <span className="flex size-11 items-center justify-center rounded-2xl bg-primary/10 text-primary">
                      {Icon ? <Icon className="size-5" aria-hidden="true" /> : `0${index + 1}`}
                    </span>
                    <ArrowUpRight
                      className="size-5 text-muted-foreground transition group-hover:-translate-y-1 group-hover:translate-x-1 group-hover:text-primary motion-reduce:transform-none"
                      aria-hidden="true"
                    />
                  </div>
                  <h3 className="mt-10 text-xl font-semibold">{value.title}</h3>
                  <p className="mt-3 leading-7 text-muted-foreground">{value.description}</p>
                </article>
              )
            })}
          </div>
        </div>
      </div>
    </section>
  )
}

import type { ReactNode } from 'react'

import { AccentButton } from '@/components/library/primitives/AccentButton'
import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type IconFeatureCardItem = {
  title: string
  description: string
  icon?: ReactNode
  action?: { label: string; href: string }
}

export type IconFeatureCardsProps = {
  title: string
  items: readonly IconFeatureCardItem[]
  eyebrow?: string
  description?: string
  columns?: 2 | 3 | 4
  tone?: AccentTone
  className?: string
}

const columnClasses = {
  2: 'sm:grid-cols-2',
  3: 'sm:grid-cols-2 lg:grid-cols-3',
  4: 'sm:grid-cols-2 lg:grid-cols-4',
}

const cardStyles: Record<AccentTone, { card: string; icon: string }> = {
  glow: {
    card: 'rounded-md bg-[#221d2f]',
    icon: 'rounded-xl bg-[#121212] text-[#ffb0eb]',
  },
  industrial: {
    card: 'border border-slate-200 bg-white',
    icon: 'bg-slate-100 text-amber-600',
  },
  'industrial-dark': {
    card: 'border border-white/10 bg-slate-900',
    icon: 'bg-slate-950 text-amber-500',
  },
}

/** Cards de diferenciais com ícone em destaque, texto e ação individual. */
export function IconFeatureCards({
  title,
  items,
  eyebrow,
  description,
  columns = 3,
  tone = 'glow',
  className,
}: IconFeatureCardsProps) {
  const t = getAccentTone(tone)
  const styles = cardStyles[tone]

  return (
    <section className={cn('w-full py-12 lg:py-16', t.section, className)}>
      <div className="container">
        <EyebrowHeading
          tone={tone}
          eyebrow={eyebrow}
          title={title}
          description={description}
          className="mb-8"
        />
        <div className={cn('grid grid-cols-1 gap-6', columnClasses[columns])}>
          {items.map((item) => (
            <article
              key={item.title}
              className={cn(
                'relative flex min-h-[240px] flex-col items-start gap-3 overflow-hidden p-6',
                styles.card,
              )}
            >
              {item.icon ? (
                <div
                  className={cn(
                    'p-4 [&_img]:h-12 [&_img]:w-12 [&_svg]:h-8 [&_svg]:w-8',
                    styles.icon,
                  )}
                  aria-hidden
                >
                  {item.icon}
                </div>
              ) : null}
              <h3
                className={cn(
                  'text-[clamp(1.25rem,2vw,1.5rem)] font-semibold',
                  tone !== 'glow' && 'uppercase tracking-wide',
                  t.strong,
                )}
              >
                {item.title}
              </h3>
              <p className={cn('m-0', t.body)}>{item.description}</p>
              {item.action ? (
                <AccentButton href={item.action.href} tone={tone} className="mt-auto">
                  {item.action.label}
                </AccentButton>
              ) : null}
              <span className={cn('absolute inset-x-0 bottom-0 h-px', t.line)} aria-hidden />
            </article>
          ))}
        </div>
      </div>
    </section>
  )
}

import Image from 'next/image'
import { Linkedin, Mail } from 'lucide-react'
import { cn } from '@/lib/utils'

export type TeamGridProps = {
  title?: string
  members: Array<{
    name: string
    role: string
    image: { src: string; alt?: string }
    bio?: string
    email?: string
    linkedin?: string
  }>
  className?: string
}

export function TeamGrid({ title, members, className }: TeamGridProps) {
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'team-title' : undefined}
    >
      <div className="container">
        {title ? (
          <h2 id="team-title" className="mb-10 text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
        ) : null}
        <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
          {members.map((member) => (
            <article key={member.name} className="overflow-hidden rounded-2xl border bg-card">
              <div className="relative aspect-[4/5] bg-muted">
                <Image
                  src={member.image.src}
                  alt={member.image.alt ?? member.name}
                  fill
                  className="object-cover"
                  sizes="(min-width: 1024px) 25vw, 50vw"
                />
              </div>
              <div className="p-5">
                <h3 className="font-semibold">{member.name}</h3>
                <p className="text-sm text-primary">{member.role}</p>
                {member.bio ? (
                  <p className="mt-3 text-sm text-muted-foreground">{member.bio}</p>
                ) : null}
                {(member.email || member.linkedin) && (
                  <div className="mt-4 flex gap-2">
                    {member.email ? (
                      <a
                        href={`mailto:${member.email}`}
                        className="rounded-md p-2 text-muted-foreground hover:bg-muted hover:text-foreground"
                        aria-label={`Enviar e-mail para ${member.name}`}
                      >
                        <Mail className="h-4 w-4" />
                      </a>
                    ) : null}
                    {member.linkedin ? (
                      <a
                        href={member.linkedin}
                        target="_blank"
                        rel="noreferrer"
                        className="rounded-md p-2 text-muted-foreground hover:bg-muted hover:text-foreground"
                        aria-label={`LinkedIn de ${member.name}`}
                      >
                        <Linkedin className="h-4 w-4" />
                      </a>
                    ) : null}
                  </div>
                )}
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  )
}

'use client'

import * as AccordionPrimitive from '@radix-ui/react-accordion'
import { MessagesSquare, Plus } from 'lucide-react'
import Link from 'next/link'
import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'

export type FAQHelpCardProps = {
  title: string
  items: ReadonlyArray<{ question: string; answer: string }>
  eyebrow?: string
  description?: string
  help?: {
    title: string
    description?: string
    icon?: ReactNode
    action?: { label: string; href: string }
  }
  /** Índice aberto inicialmente; use `null` para começar tudo fechado. */
  defaultOpen?: number | null
  className?: string
}

/** FAQ em duas colunas: título e card de ajuda à esquerda, acordeão com ícones +/× à direita. */
export function FAQHelpCard({
  title,
  items,
  eyebrow,
  description,
  help,
  defaultOpen = 0,
  className,
}: FAQHelpCardProps) {
  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container grid gap-10 lg:grid-cols-[0.75fr_1.25fr] lg:gap-12">
        <div className="lg:sticky lg:top-24 lg:self-start">
          {eyebrow ? (
            <p className="text-xs font-semibold uppercase tracking-[0.2em] text-primary">
              {eyebrow}
            </p>
          ) : null}
          <h2 className="mt-2 text-3xl font-bold tracking-tight md:text-5xl">{title}</h2>
          {description ? (
            <p className="mt-4 leading-7 text-muted-foreground">{description}</p>
          ) : null}

          {help ? (
            <div className="mt-8 rounded-2xl border bg-muted/50 p-6">
              <span className="text-primary" aria-hidden="true">
                {help.icon ?? <MessagesSquare className="h-7 w-7" />}
              </span>
              <h3 className="mt-4 text-lg font-bold">{help.title}</h3>
              {help.description ? (
                <p className="mt-1.5 text-sm leading-6 text-muted-foreground">{help.description}</p>
              ) : null}
              {help.action ? (
                <Link
                  href={help.action.href}
                  className="mt-5 inline-flex h-10 items-center rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground transition hover:bg-primary-hover focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                >
                  {help.action.label}
                </Link>
              ) : null}
            </div>
          ) : null}
        </div>

        <AccordionPrimitive.Root
          type="single"
          collapsible
          defaultValue={defaultOpen === null ? undefined : `item-${defaultOpen}`}
          className="grid content-start gap-3"
        >
          {items.map((item, index) => (
            <AccordionPrimitive.Item
              key={item.question}
              value={`item-${index}`}
              className="rounded-2xl border bg-card transition data-[state=open]:shadow-md"
            >
              <AccordionPrimitive.Header>
                <AccordionPrimitive.Trigger className="group flex w-full items-center justify-between gap-4 rounded-2xl px-5 py-5 text-left font-semibold transition hover:text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring data-[state=open]:text-primary">
                  {item.question}
                  <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full border text-primary transition group-data-[state=open]:border-primary group-data-[state=open]:bg-primary group-data-[state=open]:text-primary-foreground">
                    <Plus
                      className="h-4 w-4 transition-transform duration-300 group-data-[state=open]:rotate-45"
                      aria-hidden="true"
                    />
                  </span>
                </AccordionPrimitive.Trigger>
              </AccordionPrimitive.Header>
              <AccordionPrimitive.Content className="overflow-hidden data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down">
                <p className="px-5 pb-5 leading-7 text-muted-foreground">{item.answer}</p>
              </AccordionPrimitive.Content>
            </AccordionPrimitive.Item>
          ))}
        </AccordionPrimitive.Root>
      </div>
    </section>
  )
}

import { Quote, Star } from 'lucide-react'

import { cn } from '@/lib/utils'

export type SpotlightTestimonial = {
  quote: string
  name: string
  role?: string
  company?: string
  avatar?: { src: string; alt: string }
  rating?: number
}

export type TestimonialsSpotlightProps = {
  eyebrow?: string
  title?: string
  featured: SpotlightTestimonial
  items?: SpotlightTestimonial[]
  className?: string
}

function Author({ item }: { item: SpotlightTestimonial }) {
  return (
    <div className="flex items-center gap-3">
      {item.avatar ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={item.avatar.src}
          alt={item.avatar.alt}
          className="size-11 rounded-full object-cover"
        />
      ) : (
        <span className="flex size-11 items-center justify-center rounded-full bg-primary/10 font-semibold text-primary">
          {item.name.charAt(0)}
        </span>
      )}
      <div>
        <p className="font-semibold">{item.name}</p>
        {(item.role || item.company) && (
          <p className="text-sm text-muted-foreground">
            {[item.role, item.company].filter(Boolean).join(' · ')}
          </p>
        )}
      </div>
    </div>
  )
}

export function TestimonialsSpotlight({
  eyebrow = 'Histórias de clientes',
  title = 'Confiança construída em cada entrega.',
  featured,
  items = [],
  className,
}: TestimonialsSpotlightProps) {
  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <header className="mb-10 max-w-2xl">
          <p className="text-sm font-semibold uppercase tracking-[0.18em] text-primary">
            {eyebrow}
          </p>
          <h2 className="mt-3 text-balance text-3xl font-bold tracking-tight md:text-5xl">
            {title}
          </h2>
        </header>

        <div className="grid gap-5 lg:grid-cols-[1.4fr_1fr]">
          <article className="relative overflow-hidden rounded-3xl bg-foreground p-7 text-background md:p-10">
            <Quote className="absolute right-6 top-6 size-20 opacity-10" aria-hidden="true" />
            <div className="mb-8 flex gap-1" aria-label={`${featured.rating ?? 5} de 5 estrelas`}>
              {Array.from({ length: featured.rating ?? 5 }, (_, index) => (
                <Star key={index} className="size-4 fill-current text-amber-400" />
              ))}
            </div>
            <blockquote className="max-w-3xl text-balance text-2xl font-medium leading-relaxed md:text-3xl">
              “{featured.quote}”
            </blockquote>
            <div className="mt-10 [&_*]:text-inherit">
              <Author item={featured} />
            </div>
          </article>

          <div className="grid gap-5">
            {items.slice(0, 2).map((item) => (
              <article
                key={`${item.name}-${item.quote}`}
                className="rounded-3xl border bg-card p-6 shadow-sm transition duration-300 hover:-translate-y-1 hover:shadow-lg motion-reduce:transform-none"
              >
                <blockquote className="mb-6 leading-7 text-muted-foreground">
                  “{item.quote}”
                </blockquote>
                <Author item={item} />
              </article>
            ))}
          </div>
        </div>
      </div>
    </section>
  )
}

import type { LucideIcon } from 'lucide-react'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type ContactMethod = {
  label: string
  value: string
  href: string
  icon?: LucideIcon
}

export type ContactSplitSectionProps = {
  eyebrow?: string
  title: string
  description?: string
  methods: ContactMethod[]
  socialLinks?: Array<{ label: string; href: string }>
  form: React.ReactNode
  formTitle?: string
  className?: string
}

export function ContactSplitSection({
  eyebrow = 'Vamos conversar',
  title,
  description,
  methods,
  socialLinks = [],
  form,
  formTitle = 'Conte sobre o seu projeto',
  className,
}: ContactSplitSectionProps) {
  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="overflow-hidden rounded-[2rem] border bg-card shadow-sm">
          <div className="grid lg:grid-cols-[0.85fr_1.15fr]">
            <div className="min-w-0 bg-foreground p-7 text-background md:p-10 lg:p-12">
              <p className="text-sm font-semibold uppercase tracking-[0.18em] text-background/70">
                {eyebrow}
              </p>
              <h2 className="mt-4 text-balance text-3xl font-bold tracking-tight md:text-4xl lg:text-5xl">
                {title}
              </h2>
              {description ? (
                <p className="mt-5 max-w-md leading-7 text-background/70">{description}</p>
              ) : null}

              <address className="mt-10 space-y-3 not-italic">
                {methods.map((method) => {
                  const Icon = method.icon
                  return (
                    <a
                      key={`${method.label}-${method.value}`}
                      href={method.href}
                      className="group flex items-center gap-4 rounded-2xl border border-background/15 p-4 transition hover:bg-background/10"
                    >
                      <span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-background/10">
                        {Icon ? (
                          <Icon className="size-5" aria-hidden="true" />
                        ) : (
                          <ArrowUpRight className="size-5" />
                        )}
                      </span>
                      <span className="min-w-0">
                        <span className="block text-xs uppercase tracking-wider text-background/55">
                          {method.label}
                        </span>
                        <span className="mt-1 block font-medium [overflow-wrap:anywhere]">
                          {method.value}
                        </span>
                      </span>
                    </a>
                  )
                })}
              </address>

              {socialLinks.length ? (
                <div className="mt-8 flex flex-wrap gap-2">
                  {socialLinks.map((link) => (
                    <a
                      key={link.label}
                      href={link.href}
                      className="rounded-full border border-background/20 px-3 py-1.5 text-sm transition hover:bg-background hover:text-foreground"
                    >
                      {link.label}
                    </a>
                  ))}
                </div>
              ) : null}
            </div>

            <div className="min-w-0 p-7 md:p-10 lg:p-12">
              <h3 className="mb-7 text-2xl font-semibold">{formTitle}</h3>
              {form}
            </div>
          </div>
        </div>
      </div>
    </section>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type HeroImageProps = {
  title: string
  description?: string
  image: { src: string; alt: string }
  eyebrow?: string
  primaryAction?: { label: string; href: string }
  secondaryAction?: { label: string; href: string }
  align?: 'left' | 'center'
  className?: string
}

export function HeroImage({
  title,
  description,
  image,
  eyebrow,
  primaryAction,
  secondaryAction,
  align = 'left',
  className,
}: HeroImageProps) {
  return (
    <section
      className={cn(
        'relative isolate min-h-[560px] overflow-hidden bg-slate-950 text-white',
        className,
      )}
      aria-labelledby="hero-image-title"
    >
      <Image
        src={image.src}
        alt={image.alt}
        fill
        priority
        className="object-cover opacity-55"
        sizes="100vw"
      />
      <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/45 to-transparent" />
      <div
        className={cn(
          'container relative z-10 flex min-h-[560px] flex-col justify-center py-20',
          align === 'center' && 'items-center text-center',
        )}
      >
        {eyebrow ? (
          <p className="mb-4 text-sm font-semibold uppercase tracking-[0.2em]">{eyebrow}</p>
        ) : null}
        <h1
          id="hero-image-title"
          className="max-w-4xl text-4xl font-bold tracking-tight sm:text-6xl"
        >
          {title}
        </h1>
        {description ? <p className="mt-6 max-w-2xl text-lg text-white/80">{description}</p> : null}
        {(primaryAction || secondaryAction) && (
          <div className="mt-8 flex flex-wrap gap-3">
            {primaryAction ? (
              <Button asChild size="lg">
                <Link href={primaryAction.href}>{primaryAction.label}</Link>
              </Button>
            ) : null}
            {secondaryAction ? (
              <Button asChild size="lg" variant="secondary">
                <Link href={secondaryAction.href}>{secondaryAction.label}</Link>
              </Button>
            ) : null}
          </div>
        )}
      </div>
    </section>
  )
}

import { cn } from '@/lib/utils'

/** Logo oficial Bloomin (PNG embutido para funcionar no catálogo e nos projetos instalados). */
const BLOOMIN_LOGO_SRC =
  'data:image/png;base64,'

export const BLOOMIN_URL = 'https://bloomin.com.br'

export type BloominLogoProps = {
  className?: string
  /** Altura visual do logo (largura acompanha a proporção). */
  height?: number
}

export function BloominLogo({ className, height = 18 }: BloominLogoProps) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- data URI portátil no registry
    <img
      src={BLOOMIN_LOGO_SRC}
      alt="Bloomin"
      width={Math.round(height * (421 / 108))}
      height={height}
      className={cn('h-[1.125rem] w-auto', className)}
      style={{ height, width: 'auto' }}
    />
  )
}

export type BloominCreditProps = {
  label?: string
  href?: string
  className?: string
  /** Fundo escuro atrás do logo (o PNG oficial tem fundo preto). */
  logoClassName?: string
}

/** Crédito padrão “Desenvolvido por” com o logo da Bloomin. */
export function BloominCredit({
  label = 'Desenvolvido por',
  href = BLOOMIN_URL,
  className,
  logoClassName,
}: BloominCreditProps) {
  return (
    <span className={cn('inline-flex items-center gap-2 text-sm', className)}>
      <span className="opacity-80">{label}</span>
      <a
        href={href}
        target="_blank"
        rel="noopener noreferrer"
        aria-label="Bloomin — agência de marketing digital"
        className={cn(
          'inline-flex items-center rounded-md bg-neutral-950 px-2 py-1 transition hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
          logoClassName,
        )}
      >
        <BloominLogo height={16} />
      </a>
    </span>
  )
}

import type { ReactNode } from 'react'
import { Clock3, Mail, MapPin } from 'lucide-react'

import { cn } from '@/lib/utils'

export type ContactInfoBarItem = {
  label: string
  value: ReactNode
  href?: string
  icon?: ReactNode
}

export type ContactInfoBarProps = {
  items: readonly ContactInfoBarItem[]
  variant?: 'primary' | 'dark' | 'light'
  className?: string
}

const defaultIcons = [MapPin, Mail, Clock3]

export function ContactInfoBar({ items, variant = 'primary', className }: ContactInfoBarProps) {
  return (
    <aside
      className={cn(
        'border-b text-xs',
        variant === 'primary' && 'border-primary-foreground/10 bg-primary text-primary-foreground',
        variant === 'dark' && 'border-white/10 bg-[#10100e] text-white',
        variant === 'light' && 'bg-muted/60 text-muted-foreground',
        className,
      )}
      aria-label="Informações de contato"
    >
      <div className="container flex min-h-10 flex-wrap items-center justify-center gap-x-6 gap-y-2 py-2 md:justify-between">
        {items.map((item, index) => {
          const Icon = defaultIcons[index % defaultIcons.length]
          const content = (
            <>
              {item.icon ?? <Icon className="h-3.5 w-3.5 shrink-0" aria-hidden />}
              <span className="font-medium">{item.label}:</span>
